        b.append({'t':f,'q':q,'c':c,'h':h,'w':w,'k':0,'d':2,'id':f'fb-3B-{nid}','src':'nov5-pool'}); added.setdefault(f,[]).append(f'fb-3B-{nid}'); nid+=1
